import Foundation
import Testing
@testable import HookSpot

// Expected values were generated by running the web's src/lib/*.js under
// TZ=America/Los_Angeles, so these pin iOS ↔ web parity.

private let la: Calendar = {
    var c = Calendar(identifier: .gregorian)
    c.timeZone = TimeZone(identifier: "America/Los_Angeles")!
    return c
}()
private let laTZ = TimeZone(identifier: "America/Los_Angeles")!
private func iso(_ s: String) -> Date { try! Date(s, strategy: .iso8601) }

private func photo(_ name: String, catchId: String? = nil, ms: Double? = nil, order: Int? = nil,
                   userId: String = "u1", species: String? = nil, meta extra: [String: JSONValue] = [:]) -> Photo {
    var meta = extra
    if let order { meta["order"] = .number(Double(order)) }
    return Photo(name: name, userId: userId, catchId: catchId, time: ms.map { Date(timeIntervalSince1970: $0 / 1000) },
                 coordinate: Coordinate(latitude: 45, longitude: -121), species: species, meta: meta)
}

@Suite struct FormattersTests {
    let ts = iso("2026-03-01T03:05:00Z")

    @Test func dates() {
        #expect(Formatters.formatDateShort(ts, calendar: la) == "February 28th · 7:05pm")
        #expect(Formatters.formatDateShort(ts, hideTime: true, calendar: la) == "February 28th")
        #expect(Formatters.formatDateFull(ts, calendar: la) == "February 28th, 2026 · 7:05pm")
        #expect(Formatters.formatDateNumeric(ts, calendar: la) == "02/28/26 · 7:05pm")
        #expect(Formatters.formatDateShort(iso("2026-07-04T19:00:00Z"), calendar: la) == "July 4th · 12:00pm")
        #expect(Formatters.formatDateNumeric(iso("2026-01-11T08:09:00Z"), calendar: la) == "01/11/26 · 12:09am")
        #expect(Formatters.formatDateFull(nil) == "Unknown date")
        #expect(Formatters.formatDateShort(nil) == nil)
    }

    @Test(arguments: [(1, "1st"), (2, "2nd"), (3, "3rd"), (4, "4th"), (11, "11th"), (12, "12th"), (13, "13th"),
                      (21, "21st"), (22, "22nd"), (23, "23rd"), (24, "24th"), (31, "31st"),
                      (101, "101st"), (111, "111th"), (112, "112th"), (113, "113th")])
    func ordinals(n: Int, expected: String) {
        #expect(Formatters.ordinal(n) == expected)
    }

    @Test func text() {
        #expect(Formatters.cleanSpecies("Brown Trout (Salmo trutta)  ") == "Brown Trout")
        #expect(Formatters.cleanSpecies("none") == nil)
        #expect(Formatters.cleanGear("  5wt\u{00a0} Sage   X ") == "5wt Sage X")
        #expect(Formatters.cleanGear("   ") == nil)
        #expect(Formatters.speciesLabel("rainbow trout-steelhead o'neil") == "Rainbow Trout-Steelhead O'Neil")
    }

    @Test func location() {
        let a = photo("a", meta: ["waterBody": ["name": "Deschutes River"], "location": ["city": "Maupin", "state": "Oregon"]])
        let b = photo("b", meta: ["location": ["city": "Bend", "state": "Oregon"]])
        #expect(Formatters.formatCatchLocation(a) == "Deschutes River, Oregon")
        #expect(Formatters.formatCatchLocation(b) == "Bend, Oregon")
        #expect(Formatters.formatCatchLocation(photo("c")) == nil)
    }

    @Test func parsing() {
        #expect(DateParsing.exif("2024:03:15 10:20:30", timeZone: laTZ)?.timeIntervalSince1970 == 1710523230)
        #expect(DateParsing.timestamptz("2024-05-01T12:00:00+00:00") == iso("2024-05-01T12:00:00Z"))
        #expect(DateParsing.timestamptz("2024-05-01T12:00:00.123Z") != nil)
        #expect(DateParsing.timestamptz("2024-05-01 12:00:00+00") == iso("2024-05-01T12:00:00Z"))
        #expect(DateParsing.isoString(iso("2024-05-01T12:00:00Z")) == "2024-05-01T12:00:00.000Z")
    }
}

@Suite struct GroupingTests {
    @Test func groupPhotosMatchesWeb() {
        let photos = [photo("a", catchId: "c1", ms: 100), photo("b", catchId: "c2", ms: 300), photo("c", catchId: "c1", ms: 50, order: 1),
                      photo("d", ms: 200), photo("e", catchId: "c1", ms: 400, order: 0), photo("f"), photo("g", catchId: "c2", ms: 300)]
        let names = PhotoGrouping.groupPhotos(photos).map { $0.map(\.name) }
        #expect(names == [["e", "c", "a"], ["b", "g"], ["d"], ["f"]])
    }

    @Test func groupByTimeMatchesWeb() {
        let t = [photo("x", ms: 0), photo("y", ms: 170_000), photo("z", ms: 190_000), photo("w", ms: 200_000, order: 0)]
        #expect(PhotoGrouping.groupByTime(t).map { $0.map(\.name) } == [["x", "y"], ["w", "z"]])
    }

    @Test func mapPhotoRowFallsBackToFullImage() throws {
        let json = #"""
        {"id":"r1","user_id":"u1","catch_id":null,"filename":"IMG_1.HEIC","storage_path":"u1/IMG_1.jpg",
         "url":"https://x/full.jpg","thumb_url":null,"species":"","lat":45.1,"lng":-121.2,
         "time":"2024-05-01T12:00:00+00:00","meta":{"order":2,"custom":{"k":[1,true,null]}}}
        """#
        let row = try JSONDecoder().decode(PhotoRow.self, from: Data(json.utf8))
        let p = PhotoGrouping.mapPhotoRow(row)
        #expect(p.thumbUrl == p.url)
        #expect(p.species == nil)
        #expect(p.hasGps)
        #expect(p.order == 2)
        #expect(p.meta["custom"] == ["k": .array([1, true, .null])])
        #expect(p.key == "u1/IMG_1.HEIC")
    }

    @Test func homeCenterAveragesOwnPhotos() {
        var a = photo("a"); a.isOwn = true; a.coordinate = Coordinate(latitude: 40, longitude: -120)
        var b = photo("b"); b.isOwn = true; b.coordinate = Coordinate(latitude: 42, longitude: -122)
        let c = photo("c") // not own
        let home = PhotoGrouping.homeCenter([a, b, c])
        #expect(home?.center == Coordinate(latitude: 41, longitude: -121))
        #expect(home?.zoom == 5)
    }
}

@Suite struct ValidationTests {
    @Test(arguments: [("abc", true), ("a_b-9", true), ("ab", false), ("ABC", false), ("has space", false),
                      (String(repeating: "a", count: 20), true), (String(repeating: "a", count: 21), false)])
    func usernames(name: String, ok: Bool) {
        #expect(Validation.isValidUsername(name) == ok)
    }

    @Test func storageKeys() {
        #expect(StorageKeys.storageKey("My Fish (1).HEIC") == "My_Fish__1_.jpg")
        #expect(StorageKeys.storageKey("a.heif") == "a.jpg")
        #expect(StorageKeys.storageKey("🐟.png") == "__.png") // one emoji = two UTF-16 units, as in JS
        #expect(StorageKeys.thumbPath(for: "u1/IMG_1.jpg") == "u1/thumbs/IMG_1.jpg")
        #expect(StorageKeys.photoPath(userId: "u1", filename: "a b.jpg") == "u1/a_b.jpg")
    }

    @Test func photoInsertOmitsThumbURLWhenMissing() throws {
        func encode(_ thumb: String?) throws -> [String: Any] {
            let row = UploadService.PhotoInsert(user_id: "u", catch_id: "c", filename: "f", storage_path: "u/f", url: "x",
                                                thumb_url: thumb, species: nil, lat: nil, lng: nil, time: nil, meta: [:])
            return try JSONSerialization.jsonObject(with: JSONEncoder().encode(row)) as! [String: Any]
        }
        #expect(try encode(nil)["thumb_url"] == nil)          // key absent — never sent as null
        #expect(try encode("t")["thumb_url"] as? String == "t")
    }
}

@Suite struct StatsTests {
    @Test func aggregates() {
        let now = iso("2026-10-15T12:00:00Z")
        let groups: [PhotoGroup] = [
            [photo("a", catchId: "1", ms: iso("2026-10-01T18:00:00Z").timeIntervalSince1970 * 1000, species: "brown trout",
                   meta: ["rod": "5wt Sage", "weather": ["temp": 61, "condition": "Clear"]])],
            [photo("b", catchId: "2", ms: iso("2026-09-10T18:00:00Z").timeIntervalSince1970 * 1000, species: "Brown Trout (Salmo trutta)",
                   meta: ["rod": "5WT  sage", "weather": ["temp": 48, "condition": "Rain"]])],
            [photo("c", catchId: "3", ms: iso("2025-01-10T18:00:00Z").timeIntervalSince1970 * 1000, species: "Rainbow trout")],
        ]
        let s = StatsAggregations.compute(groups, now: now, calendar: la)
        #expect(s.totalLabel == "3 catches")
        #expect(s.monthly.count == 12)
        #expect(s.monthly.last?.count == 1)
        #expect(s.monthly[10].count == 1)
        #expect(s.monthly.map(\.count).reduce(0, +) == 2) // Jan 2025 is outside the window
        #expect(s.hourly[11] == 2)                         // 18:00Z = 11am PDT
        #expect(s.hourly[10] == 1)                         // 18:00Z in January = 10am PST
        #expect(s.species == [CountEntry(label: "Brown Trout", count: 2), CountEntry(label: "Rainbow Trout", count: 1)])
        #expect(s.rods == [CountEntry(label: "5wt Sage", count: 2)])
        #expect(s.weatherConditions.map(\.label) == ["Clear", "Rain"])
        #expect(s.temperatureBuckets.map(\.label) == ["40–49°", "60–69°"])
        #expect(s.speciesMonthly.first?.counts.last?.count == 1)
    }

    @Test func emptyStats() {
        #expect(StatsAggregations.compute([]).totalLabel == "0 catches")
    }
}

@Suite struct EnrichmentTests {
    @Test func weatherSlotMirrorsWebQuirk() {
        // 2026-03-01T03:05Z: UTC date is Mar 1, LA-local hour is 19 → web looks up "2026-03-01T19:00".
        let slot = EnrichmentService.weatherTarget(for: iso("2026-03-01T03:05:00Z"), localCalendar: la)
        #expect(slot.dateStr == "2026-03-01")
        #expect(slot.target == "2026-03-01T19:00")
    }

    @Test func limiterCapsConcurrency() async {
        actor Counter { var now = 0, peak = 0
            func enter() { now += 1; peak = max(peak, now) }
            func leave() { now -= 1 } }
        let limiter = AsyncLimiter(limit: 3)
        let counter = Counter()
        await withTaskGroup(of: Void.self) { g in
            for _ in 0..<12 {
                g.addTask {
                    await limiter.run {
                        await counter.enter()
                        try? await Task.sleep(for: .milliseconds(20))
                        await counter.leave()
                    }
                }
            }
        }
        #expect(await counter.peak <= 3)
    }
}
